#!/usr/bin/env python3
"""Strip (* *) comments, blank lines, and the verification-only definitions
from a Fortress .fss file.  One rule, applied identically to every file it is
pointed at, so before/after counts are comparable.

Excluded as verification-only: initW, goldRow, goldRows, goldMat, goldHeads,
goldenCheck (definitions) and the bare `goldenCheck()` call.
"""
import re, sys

EXCLUDE = {"initW", "goldRow", "goldRows", "goldMat", "goldHeads", "goldenCheck"}


def strip_comments(src):
    out, depth, i = [], 0, 0
    while i < len(src):
        if src.startswith("(*", i):
            depth += 1
            i += 2
        elif src.startswith("*)", i) and depth:
            depth -= 1
            i += 2
        else:
            if not depth:
                out.append(src[i])
            i += 1
    return "".join(out)


def blocks(lines):
    """Group into top-level blocks: a block starts at a column-0 line and runs
    through following indented lines (and a closing column-0 `end`)."""
    bs, cur = [], []
    for l in lines:
        top = (l[:1] not in (" ", "\t"))
        if top and cur and not (l.strip() == "end" and any(
                b.rstrip().endswith(("do", "}", ")")) or True for b in cur[:1])):
            pass
        if top and l.strip() == "end" and cur:
            cur.append(l)
            continue
        if top and cur:
            bs.append(cur)
            cur = [l]
        else:
            cur.append(l)
    if cur:
        bs.append(cur)
    return bs


def name_of(block):
    first = block[0]
    m = re.match(r"\s*(?:object|trait)\s+([A-Za-z_][\w]*)", first)
    if m:
        return m.group(1)
    m = re.match(r"\s*([A-Za-z_][\w]*)\s*[(:=]", first)
    if m:
        return m.group(1)
    return None


def main(path):
    src = strip_comments(open(path).read())
    lines = [l.rstrip() for l in src.split("\n")]
    lines = [l for l in lines if l.strip()]
    out = []
    for b in blocks(lines):
        if name_of(b) in EXCLUDE:
            continue
        out.extend(l for l in b if l.strip() != "goldenCheck()")
    sys.stdout.write("\n".join(out) + "\n")


main(sys.argv[1])

